-- Survey masters, workflow, customer confirmation, packing plan inputs, and starter data for PostgreSQL.
BEGIN;
CREATE TABLE "HouseholdItems" ("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"Code" VARCHAR(40) NOT NULL,"Name" VARCHAR(160) NOT NULL,"VolumeCbm" NUMERIC(12,3) NOT NULL,"Description" VARCHAR(500),"IsActive" BOOLEAN NOT NULL,UNIQUE("TenantId","Code")); CREATE INDEX "IX_HouseholdItems_Tenant" ON "HouseholdItems"("TenantId");
CREATE TABLE "PackingMaterials" ("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"Code" VARCHAR(40) NOT NULL,"Name" VARCHAR(160) NOT NULL,"Unit" VARCHAR(40) NOT NULL,"CurrentUnitCost" NUMERIC(18,2) NOT NULL,"Description" VARCHAR(500),"IsActive" BOOLEAN NOT NULL,UNIQUE("TenantId","Code")); CREATE INDEX "IX_PackingMaterials_Tenant" ON "PackingMaterials"("TenantId");
CREATE TABLE "BoxTypes" ("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"Code" VARCHAR(40) NOT NULL,"Name" VARCHAR(160) NOT NULL,"CapacityCbm" NUMERIC(12,3) NOT NULL,"Description" VARCHAR(500),"IsActive" BOOLEAN NOT NULL,UNIQUE("TenantId","Code")); CREATE INDEX "IX_BoxTypes_Tenant" ON "BoxTypes"("TenantId");
CREATE TABLE "BoxTypeMaterials" ("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"BoxTypeId" UUID NOT NULL REFERENCES "BoxTypes"("Id") ON DELETE CASCADE,"MaterialId" UUID NOT NULL REFERENCES "PackingMaterials"("Id"),"Quantity" NUMERIC(12,3) NOT NULL,UNIQUE("BoxTypeId","MaterialId")); CREATE INDEX "IX_BoxTypeMaterials_Tenant" ON "BoxTypeMaterials"("TenantId");
CREATE TABLE "Surveys" ("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"SurveyNumber" VARCHAR(40) NOT NULL,"SalesLeadId" UUID REFERENCES "SalesLeads"("Id"),"CustomerName" VARCHAR(160) NOT NULL,"Phone" VARCHAR(40) NOT NULL,"Email" VARCHAR(254),"AssignedEmployeeId" UUID NOT NULL REFERENCES "Employees"("Id"),"ScheduledAtUtc" TIMESTAMPTZ NOT NULL,"Address" VARCHAR(600) NOT NULL,"Latitude" NUMERIC(10,7),"Longitude" NUMERIC(10,7),"Status" VARCHAR(30) NOT NULL,"Notes" VARCHAR(2000),"StartedAtUtc" TIMESTAMPTZ,"EndedAtUtc" TIMESTAMPTZ,"ScheduleConfirmedAtUtc" TIMESTAMPTZ,"ItemsConfirmedAtUtc" TIMESTAMPTZ,"CustomerNotes" VARCHAR(2000),"ConfirmationTokenHash" VARCHAR(64),"ConfirmationExpiresAtUtc" TIMESTAMPTZ,"CreatedAtUtc" TIMESTAMPTZ NOT NULL,"UpdatedAtUtc" TIMESTAMPTZ NOT NULL,UNIQUE("TenantId","SurveyNumber")); CREATE UNIQUE INDEX "UX_Surveys_ConfirmationToken" ON "Surveys"("ConfirmationTokenHash") WHERE "ConfirmationTokenHash" IS NOT NULL; CREATE INDEX "IX_Surveys_Tenant_Latest" ON "Surveys"("TenantId","SerialNo" DESC); CREATE INDEX "IX_Surveys_Assignee_Date" ON "Surveys"("AssignedEmployeeId","ScheduledAtUtc");
CREATE TABLE "SurveyRooms" ("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"SurveyId" UUID NOT NULL REFERENCES "Surveys"("Id") ON DELETE CASCADE,"Name" VARCHAR(120) NOT NULL,"DisplayOrder" INTEGER NOT NULL); CREATE INDEX "IX_SurveyRooms_Tenant" ON "SurveyRooms"("TenantId"); CREATE INDEX "IX_SurveyRooms_Survey" ON "SurveyRooms"("SurveyId");
CREATE TABLE "SurveyItems" ("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"SurveyId" UUID NOT NULL REFERENCES "Surveys"("Id") ON DELETE CASCADE,"RoomId" UUID NOT NULL REFERENCES "SurveyRooms"("Id"),"HouseholdItemId" UUID NOT NULL REFERENCES "HouseholdItems"("Id"),"Quantity" INTEGER NOT NULL,"VolumePerUnitCbm" NUMERIC(12,3) NOT NULL,"Notes" VARCHAR(500)); CREATE INDEX "IX_SurveyItems_Tenant" ON "SurveyItems"("TenantId"); CREATE INDEX "IX_SurveyItems_Survey" ON "SurveyItems"("SurveyId");
CREATE TABLE "SurveyExtraMaterials" ("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"SurveyId" UUID NOT NULL REFERENCES "Surveys"("Id") ON DELETE CASCADE,"MaterialId" UUID NOT NULL REFERENCES "PackingMaterials"("Id"),"Quantity" NUMERIC(12,3) NOT NULL,UNIQUE("SurveyId","MaterialId")); CREATE INDEX "IX_SurveyExtraMaterials_Tenant" ON "SurveyExtraMaterials"("TenantId");

INSERT INTO "HouseholdItems"("Id","TenantId","Code","Name","VolumeCbm","Description","IsActive") SELECT (md5(t."Id"::text||':item:'||d.code))::uuid,t."Id",d.code,d.name,d.volume,d.description,TRUE FROM "Tenants" t CROSS JOIN (VALUES ('KING_BED','King bed',5.000,'King bed including frame'),('QUEEN_BED','Queen bed',4.000,'Queen bed including frame'),('CHAIR','Dining chair',1.000,'Standard chair'),('BIG_SOFA','Large sofa',3.000,'Three or four-seat sofa'),('DINING_TABLE','Dining table',2.500,'Six-seat dining table'),('WARDROBE','Wardrobe',4.500,'Large wardrobe'),('TV_55','Television 55 inch',0.500,'Flat-screen television'),('FRIDGE','Refrigerator',1.500,'Double-door refrigerator')) d(code,name,volume,description) ON CONFLICT("TenantId","Code") DO NOTHING;
INSERT INTO "PackingMaterials"("Id","TenantId","Code","Name","Unit","CurrentUnitCost","Description","IsActive") SELECT (md5(t."Id"::text||':material:'||d.code))::uuid,t."Id",d.code,d.name,d.unit,d.cost,d.description,TRUE FROM "Tenants" t CROSS JOIN (VALUES ('CARDBOARD','Corrugated cardboard','sheet',120.00,'Box wall material'),('TAPE','Packing tape','roll',75.00,'Heavy-duty tape'),('BUBBLE_WRAP','Bubble wrap','meter',35.00,'Fragile-item wrapping'),('FOAM','Protective foam','sheet',55.00,'Impact protection'),('STRETCH_WRAP','Stretch wrap','roll',280.00,'Furniture and surface protection')) d(code,name,unit,cost,description) ON CONFLICT("TenantId","Code") DO NOTHING;
INSERT INTO "BoxTypes"("Id","TenantId","Code","Name","CapacityCbm","Description","IsActive") SELECT (md5(t."Id"::text||':box:'||d.code))::uuid,t."Id",d.code,d.name,d.capacity,d.description,TRUE FROM "Tenants" t CROSS JOIN (VALUES ('SMALL','Small box',1.000,'Small household carton'),('MEDIUM','Medium box',3.000,'General household carton'),('LARGE','Large box',5.000,'Large-item carton'),('XL','Extra-large crate',8.000,'Reinforced crate for bulky items')) d(code,name,capacity,description) ON CONFLICT("TenantId","Code") DO NOTHING;
INSERT INTO "BoxTypeMaterials"("Id","TenantId","BoxTypeId","MaterialId","Quantity") SELECT (md5(b."Id"::text||':'||m."Id"::text))::uuid,b."TenantId",b."Id",m."Id",r.quantity FROM "BoxTypes" b JOIN (VALUES ('SMALL','CARDBOARD',2.0),('SMALL','TAPE',0.15),('MEDIUM','CARDBOARD',3.0),('MEDIUM','TAPE',0.25),('LARGE','CARDBOARD',5.0),('LARGE','TAPE',0.40),('LARGE','FOAM',1.0),('XL','CARDBOARD',8.0),('XL','TAPE',0.75),('XL','FOAM',2.0)) r(box_code,material_code,quantity) ON r.box_code=b."Code" JOIN "PackingMaterials" m ON m."TenantId"=b."TenantId" AND m."Code"=r.material_code ON CONFLICT("BoxTypeId","MaterialId") DO NOTHING;
COMMIT;
